// План specs/landing.md, 1.2 (кейс LND-02). Гость на https://techory.ai. Только чтение. @prod-safe
import { test, expect } from '@playwright/test';
import { LOGO_SRC, PRODUCT_IMAGES, fileName, openLanding, productImages } from './landing-helpers';

test.describe('Landing — скриншоты системы (#99cf43b7)', () => {
  test('Landing has no images other than the logo and the 4 new screenshots #99cf43b7 @desktop @prod-safe', async ({ page }) => {
    await openLanding(page);
    // Прокрутить до последнего скриншота и подвала — вся страница отрисована
    await productImages(page).last().scrollIntoViewIfNeeded();
    await page.getByRole('img', { name: 'Techory', exact: true }).last().scrollIntoViewIfNeeded();

    // Каждый <img> — логотип или один из 4 новых скриншотов
    const srcs = await page.locator('img').evaluateAll((els) => els.map((e) => (e as HTMLImageElement).src));
    for (const src of srcs) {
      const allowed = LOGO_SRC.test(new URL(src).pathname) || (src.includes('/product/') && PRODUCT_IMAGES.includes(fileName(src)));
      expect(allowed, `лишнее изображение: ${src}`).toBe(true);
    }

    // Нет картинок-фонов (старых скриншотов/иллюстраций в CSS)
    const bgs = await page.evaluate(() =>
      [...document.querySelectorAll('*')]
        .map((e) => getComputedStyle(e).backgroundImage)
        .filter((b) => b && b.includes('url(')),
    );
    expect(bgs).toEqual([]);
  });
});
